pair A, B, C, D, P;
pair[] M;

A = dir(118);
B = dir(62);
C = dir(323);
D = dir(165);
M[12] = (A + B)/2;
M[13] = (A + C)/2;
M[14] = (A + D)/2;
M[23] = (B + C)/2;
M[24] = (B + D)/2;
M[34] = (C + D)/2;
P = (A + B + C + D)/2;

draw(Circle((0,0),1),red);
draw(A--B,green);
draw(A--C,green);
draw(A--D,green);
draw(B--C,green);
draw(B--D,green);
draw(C--D,green);
